import { createHash } from 'node:crypto';
import { mkdirSync, mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { expect, type ElectronApplication, type Page } from '@playwright/test';
import { PACK_FORMAT, PACK_MANIFEST } from '../../src/shared/model-packs';
import { chooseMenuItem } from './helpers';

/*
 * Caption AI's end-to-end fixtures (alpha.22, cap-integration): a placeholder Gujarati "model" (generated bytes,
 * never a real model) in an offline model pack (cap-pack's format), and the list that makes this copy of Drashti
 * know it by its size and SHA-256 (DRASHTI_TEST_SPEECH_MODELS, cap-whisper's). The stand-in recognizer
 * (DRASHTI_TEST_SPEECH) still does the hearing: nothing is loaded from the file.
 */

const LICENCE = 'Placeholder Apache-2.0 licence text, for the tests.';
const sha = (b: Buffer) => createHash('sha256').update(b).digest('hex');

export interface PlaceholderCaptionPack {
  /** The pack's folder, to import. */
  folder: string;
  /** The known-models list, for DRASHTI_TEST_SPEECH_MODELS. */
  list: string;
}

/**
 * Route W (the default): one whisper.cpp file. Route C (`conformer`): AI4Bharat IndicConformer's three files
 * (model.onnx, tokens.txt, frontend.bin) in IndicConformer's format, known by the model.onnx file. `files`: Route C's
 * three files as given (the generated test graph of scripts/indic-fixture.mjs, which Drashti's helper really runs).
 */
export function placeholderCaptionPack(
  o: { conformer?: boolean; files?: { model: Buffer; tokens: Buffer; frontend: Buffer } } = {},
): PlaceholderCaptionPack {
  const root = mkdtempSync(join(tmpdir(), 'drashti-e2e-caption-ai-'));
  const folder = join(root, 'Placeholder caption pack');
  const model = o.files?.model ?? Buffer.from(Array.from({ length: 8_192 }, (_, i) => (i * 13 + 1) % 251));
  const tokens = o.files?.tokens ?? Buffer.from('<blk>\nplaceholder\n');
  const frontend =
    o.files?.frontend ?? Buffer.from(Array.from({ length: 1_024 }, (_, i) => (i * 7 + 3) % 251));
  const modelFiles: [string, Buffer][] = o.conformer
    ? [
        ['captions/gu-conformer/model.onnx', model],
        ['captions/gu-conformer/tokens.txt', tokens],
        ['captions/gu-conformer/frontend.bin', frontend],
      ]
    : [['captions/gu/model.bin', model]];
  const files = new Map<string, Buffer>([['licences/Apache-2.0.txt', Buffer.from(LICENCE)], ...modelFiles]);
  const manifest = {
    format: PACK_FORMAT,
    version: 1,
    id: 'placeholder-caption-pack',
    name: 'Placeholder caption models',
    release: '2026.11.24',
    files: [
      {
        name: 'licences/Apache-2.0.txt',
        bytes: Buffer.byteLength(LICENCE),
        sha256: sha(Buffer.from(LICENCE)),
        licence: 'Apache-2.0',
        purpose: ['licence'],
      },
      ...modelFiles.map(([name, data]) => ({
        name,
        bytes: data.length,
        sha256: sha(data),
        licence: 'Apache-2.0',
        purpose: ['captions-gu'],
        model: 'placeholder-gu-pack',
        format: o.conformer ? 'indicconformer-ctc-onnx-v1' : 'whisper-ggml',
        // A pack credits each model (cap-pack refuses one that does not).
        attribution: 'Placeholder Gujarati model, made by the tests',
        licenceFile: 'licences/Apache-2.0.txt',
      })),
    ],
  };
  files.set(PACK_MANIFEST, Buffer.from(JSON.stringify(manifest, null, 2)));
  for (const [name, data] of files) {
    mkdirSync(dirname(join(folder, name)), { recursive: true });
    writeFileSync(join(folder, name), data);
  }
  const list = join(root, 'models.json');
  writeFileSync(
    list,
    JSON.stringify([
      {
        id: 'placeholder-gu',
        language: 'gu',
        name: 'Placeholder Gujarati',
        bytes: model.length,
        sha256: sha(model),
        licence: 'Apache-2.0',
        fallback: false,
        timestamps: false,
        // A Route C model pins its tokens and front-end files too (review M2).
        ...(o.conformer
          ? {
              format: 'indicconformer-ctc-onnx-v1',
              companions: [
                { name: 'tokens.txt', bytes: tokens.length, sha256: sha(tokens) },
                { name: 'frontend.bin', bytes: frontend.length, sha256: sha(frontend) },
              ],
            }
          : {}),
      },
    ]),
  );
  return { folder, list };
}

/** Help › Caption and Translation Models…: import the pack (the open dialog answers with its folder), then close. */
export async function importCaptionPack(app: ElectronApplication, win: Page, folder: string): Promise<void> {
  await app.evaluate(({ dialog }, f) => {
    dialog.showOpenDialog = () => Promise.resolve({ canceled: false, filePaths: [f] });
  }, folder);
  await chooseMenuItem(app, 'model-packs');
  const packs = win.getByTestId('model-packs-dialog');
  await packs.getByTestId('model-packs-import-folder').click();
  await expect(packs.getByTestId('model-packs-notice')).toHaveText(
    'Placeholder caption models is installed on this computer, every file checked.',
  );
  await packs.getByRole('button', { name: 'Close', exact: true }).click();
  await expect(packs).toHaveCount(0);
}

/** In Live Captions: Gujarati's own model chosen (from the pack), then Gujarati as the speaker's language. */
export async function chooseGujaratiOwnModel(
  app: ElectronApplication,
  dialog: ReturnType<Page['getByTestId']>,
) {
  await dialog.getByTestId('captions-language-model-gu-choice').selectOption('placeholder-gu');
  await expect(dialog.getByTestId('captions-language-model-gu')).toHaveAttribute('data-phase', 'ready');
  await chooseMenuItem(app, 'speaker-language-gu');
  await expect(dialog.getByTestId('captions-language')).toHaveValue('gu');
}
